# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">ÖTELEME KİNETİK ENERJİSİ VE İŞ-ENERJİ TEOREMİ (FİZ.10.2.4)</text>\n  <rect x="20" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">ÖTELEME KİNETİK ENERJİSİ MODELİ</text>\n  <rect x="65" y="76" width="230" height="36" rx="6" fill="#dbeafe" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="99" text-anchor="middle" font-size="14" font-weight="bold" fill="#1e3a8a">Ek = (1/2) · m · v²</text>\n  <text x="34" y="132" font-size="10.8" fill="#1e3a8a">• m : Cismin kütlesi (kg) — Doğru orantılı</text>\n  <text x="34" y="152" font-size="10.8" fill="#1e3a8a">• v : Cismin sürati / hız büyüklüğü (m/s)</text>\n  <text x="34" y="172" font-size="10.8" fill="#1e3a8a">• Hız 2 katına çıkarsa Ek 4 katına çıkar!</text>\n  <text x="34" y="192" font-size="10.8" fill="#1e3a8a">• Skaler ve türetilmiş büyüklüktür; birimi Joule (J).</text>\n  <rect x="360" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">NET İŞ - KİNETİK ENERJİ DEĞİŞİMİ</text>\n  <rect x="405" y="76" width="230" height="36" rx="6" fill="#dcfce7" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="99" text-anchor="middle" font-size="13.5" font-weight="bold" fill="#14532d">Wnet = ΔEk = Ek(son) - Ek(ilk)</text>\n  <text x="374" y="132" font-size="10.8" fill="#14532d">• Net kuvvet hareket yönündeyse: Wnet &gt; 0 (Ek artar)</text>\n  <text x="374" y="152" font-size="10.8" fill="#14532d">• Net kuvvet harekete zıtsa: Wnet &lt; 0 (Ek azalır)</text>\n  <text x="374" y="172" font-size="10.8" fill="#14532d">• Net kuvvet sıfırsa (sabit hız): Wnet = 0 (Ek sabit)</text>\n  <text x="374" y="192" font-size="10.8" fill="#14532d">• Fren mesafesi süratin karesiyle (v²) doğru orantılıdır.</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.3" font-weight="bold" fill="#1e293b">SI birim sisteminde 1 Joule = 1 N·m = 1 kg·m²/s² eşitliği geçerlidir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">YER ÇEKİMİ POTANSİYEL ENERJİSİ VE ESNEKLİK POTANSİYEL ENERJİSİ</text>\n  <rect x="20" y="42" width="320" height="175" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="180" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">YER ÇEKİMİ POTANSİYEL ENERJİSİ</text>\n  <rect x="65" y="76" width="230" height="36" rx="6" fill="#fde68a" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="180" y="99" text-anchor="middle" font-size="14" font-weight="bold" fill="#78350f">Ep(çekim) = m · g · h = G · h</text>\n  <text x="34" y="132" font-size="10.8" fill="#78350f">• m : Kütle (kg), g : Çekim ivmesi (m/s² veya N/kg)</text>\n  <text x="34" y="152" font-size="10.8" fill="#78350f">• h : Seçilen referans düzeyine dik yükseklik (m)</text>\n  <text x="34" y="172" font-size="10.8" fill="#78350f">• Düzgün katı cisimlerde h, kütle merkezinin yüksekliğidir.</text>\n  <text x="34" y="192" font-size="10.8" fill="#78350f">• Yer çekimine karşı yapılan iş ΔEp kadar enerji depolar.</text>\n  <rect x="360" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">HOOKE YASASI VE ESNEKLİK POTANSİYELİ</text>\n  <rect x="405" y="76" width="230" height="36" rx="6" fill="#f3e8ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="99" text-anchor="middle" font-size="13.5" font-weight="bold" fill="#581c87">Fyay = -k · x   |   Ep(yay) = (1/2) · k · x²</text>\n  <text x="374" y="132" font-size="10.8" fill="#581c87">• k : Yay sabiti (N/m) — Yayın cinsine ve boyuna bağlı</text>\n  <text x="374" y="152" font-size="10.8" fill="#581c87">• x : Denge konumundan sıkışma veya uzama miktarı (m)</text>\n  <text x="374" y="172" font-size="10.8" fill="#581c87">• F - x grafiğinin altındaki üçgen alanı = (1/2)·k·x²</text>\n  <text x="374" y="192" font-size="10.8" fill="#581c87">• Uzama 3 katına çıkarsa yay enerjisi 9 katına çıkar!</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.3" font-weight="bold" fill="#1e293b">Bir yayın boyu kısaltılırsa (bölünürse) yay sertleşir ve yay sabiti (k) ters orantılı olarak büyür.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="25" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">MEKANİK ENERJİ BİLEŞENLERİ VE F - x GRAFİĞİ YORUMU</text>\n  <rect x="20" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="180" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#065f46">MEKANİK ENERJİ (Emekanik)</text>\n  <rect x="45" y="76" width="270" height="34" rx="6" fill="#d1fae5" stroke="#10b981" stroke-width="1.5"/>\n  <text x="180" y="98" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#064e3b">Em = Ek + Ep(çekim) + Ep(esneklik)</text>\n  <text x="34" y="130" font-size="10.8" fill="#064e3b">• Bir sistemin sahip olduğu kinetik ve potansiyel</text>\n  <text x="34" y="148" font-size="10.8" fill="#064e3b">  enerjilerin skaler toplamına Mekanik Enerji denir.</text>\n  <text x="34" y="168" font-size="10.8" fill="#064e3b">• Sürtünmesiz ortamda dış kuvvet iş yapmıyorsa</text>\n  <text x="34" y="186" font-size="10.8" fill="#064e3b">  kinetik ve potansiyel birbirine dönüşür, Em korunur.</text>\n  <rect x="360" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="520" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">YAYDA KUVVET - UZAMA (F - x) BAĞINTISI</text>\n  <line x1="400" y1="185" x2="640" y2="185" stroke="#334155" stroke-width="2"/>\n  <line x1="400" y1="185" x2="400" y2="80" stroke="#334155" stroke-width="2"/>\n  <polygon points="400,185 590,185 590,95" fill="#fed7aa" stroke="#ea580c" stroke-width="2"/>\n  <text x="382" y="100" font-size="11" font-weight="bold" fill="#9a3412">F</text>\n  <text x="585" y="202" font-size="11" font-weight="bold" fill="#9a3412">x</text>\n  <text x="525" y="158" font-size="10.5" font-weight="bold" fill="#7c2d12">Alan = (F·x)/2</text>\n  <text x="525" y="174" font-size="10.5" font-weight="bold" fill="#7c2d12">Ep = (1/2)kx²</text>\n  <text x="430" y="108" font-size="10.5" fill="#7c2d12">Eğim = F/x = k (Yay sabiti)</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.3" font-weight="bold" fill="#1e293b">Yay kuvveti-uzama grafiğinin eğimi yay sabitini (k), altındaki alan ise esneklik potansiyel enerjisini verir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
